        "\u591A\u5024\u5F93\u5C5E\u306F1\u3064\u306E\u5024\u306B\u5BFE\u5FDC\u3059\u308B\u5024\u304C\u96C6\u5408\u306B\u306A\u308B\u5F93\u5C5E\u6027\u3067\u3001\u95A2\u6570\u5F93\u5C5E\u6027\u3068\u306F\u7570\u306A\u308B\u7A2E\u985E\u306E\u5F93\u5C5E\u6027\u3002"
