      question: "\u95A2\u6570\u5F93\u5C5E\u6027\u306E\u53F3\u8FBA\u306B\u95A2\u4FC2\u8868\u306E\u6B8B\u308A\u5168\u3066\u306E\u5217\u304C\u73FE\u308C\u308B\u3068\u304D\u3001\u305D\u306E\u6C7A\u5B9A\u9805\u3092\u4F55\u3068\u3044\u3046\u304B\u3002",
