        "\u76F8\u4E92\u975E\u5354\u529B\u5229\u5F97\u306F\u4E21\u8005\u3068\u3082\u975E\u5354\u529B\u3092\u9078\u3093\u3060\u3068\u304D\u306E\u5229\u5F97\u306E\u3053\u3068\u3067\u3001\u3053\u306E\u8A2D\u554F\u306E\u72B6\u6CC1\u3068\u306F\u7570\u306A\u308B\u3002",
