        "\u5404\u5217\u3067U\u306E\u5229\u5F97(4,2,5)\u306FD\u306E\u5229\u5F97(1,0,3)\u3088\u308A\u3059\u3079\u3066\u5927\u304D\u304F\u3001D\u304CU\u3088\u308A\u512A\u308C\u3066\u3044\u308B\u7B87\u6240\u306F\u306A\u3044\u305F\u3081\u3001D\u304CU\u3092\u652F\u914D\u3059\u308B\u3053\u3068\u306F\u306A\u3044\u3002",
