        "\u300C\u5224\u65AD\u300D\u306F\u3072\u3057\u5F62\u3067\u6761\u4EF6\u5206\u5C90\u3092\u8868\u3059\u8A18\u53F7\u3067\u3001\u53CD\u5FA9\u306E\u7BC4\u56F2\u3092\u8868\u3059\u8A18\u53F7\u3067\u306F\u306A\u3044\u3002",
