        "\u30E9\u30A6\u30F3\u30C9\u30ED\u30D3\u30F3\u30B9\u30B1\u30B8\u30E5\u30FC\u30EA\u30F3\u30B0\u306F\u5404\u30D7\u30ED\u30BB\u30B9\u306B\u9806\u756A\u306B\u30AF\u30AA\u30F3\u30BF\u30E0\u3092\u5272\u308A\u5F53\u3066\u308B\u65B9\u5F0F\u3067\u3001\u51E6\u7406\u6642\u9593\u306E\u77ED\u3055\u3092\u512A\u5148\u3059\u308B\u65B9\u5F0F\u3068\u306F\u7570\u306A\u308B\u3002",
        "\u512A\u5148\u5EA6\u30B9\u30B1\u30B8\u30E5\u30FC\u30EA\u30F3\u30B0\u306F\u51E6\u7406\u6642\u9593\u3067\u306F\u306A\u304F\u5225\u9014\u5B9A\u3081\u305F\u512A\u5148\u5EA6\u306B\u57FA\u3065\u3044\u3066\u5B9F\u884C\u3059\u308B\u65B9\u5F0F\u3067\u3042\u308A\u3001\u51E6\u7406\u6642\u9593\u306E\u77ED\u3055\u3092\u57FA\u6E96\u306B\u3059\u308B\u65B9\u5F0F\u3067\u306F\u306A\u3044\u3002"
