        "\u7269\u7406\u30D5\u30EC\u30FC\u30E0\u756A\u53F7\u306F\u30DA\u30FC\u30B8\u30C6\u30FC\u30D6\u30EB\u3092\u5F15\u3044\u305F\u5F8C\u306B\u5F97\u3089\u308C\u308B\u5909\u63DB\u7D50\u679C\u3067\u3042\u308A\u3001\u4EEE\u60F3\u30A2\u30C9\u30EC\u30B9\u306E\u4E0A\u4F4D\u30D3\u30C3\u30C8\u305D\u306E\u3082\u306E\u304C\u76F4\u63A5\u793A\u3059\u5024\u3067\u306F\u306A\u3044\u3002",
        "\u30BB\u30B0\u30E1\u30F3\u30C8\u756A\u53F7\u306F\u30BB\u30B0\u30E1\u30F3\u30C6\u30FC\u30B7\u30E7\u30F3\u65B9\u5F0F\u3067\u4F7F\u308F\u308C\u308B\u533A\u5206\u3067\u3042\u308A\u3001\u5358\u7D14\u306A\u30DA\u30FC\u30B8\u30F3\u30B0\u306E\u4EEE\u60F3\u30A2\u30C9\u30EC\u30B9\u306E\u4E0A\u4F4D\u30D3\u30C3\u30C8\u304C\u793A\u3059\u3082\u306E\u3067\u306F\u306A\u3044\u3002"
